1	//! `cargo xtask`: the project's own tasks, modelled on vc-x1's.
2	//!
3	//! - `cargo xtask version` prints the version in `Cargo.toml`.
4	//! - `cargo xtask bump <next|bare|VERSION>` sets it: `next` adds one to
5	//!   the suffix's last number, `0.85.22-8` to `0.85.22-9`, and gives a
6	//!   bare version its first, `-0`, `bare` drops the suffix, a
7	//!   close-out's version, and anything else is the version as written.
8	//!   `Cargo.lock` is refreshed in the same step, since the build is
9	//!   `--locked`.
10	//! - `cargo xtask completions [NAME...]` prints a bash function that
11	//!   completes `cargo xtask` and each NAME, a shell alias for it, by
12	//!   asking the xtask of the repo the shell is in.
13	//!
14	//! The manifest is edited by `toml_edit`, which keeps its comments,
15	//! layout, and key order and changes the one value. The arguments are
16	//! clap's, whose completion engine answers when `COMPLETE` is set.
17	
18	use std::path::{Path, PathBuf};
19	use std::process::ExitCode;
20	
21	use clap::{CommandFactory, Parser, Subcommand};
22	use clap_complete::CompleteEnv;
23	use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};
24	use toml_edit::{DocumentMut, value};
25	
26	/// The project's own tasks.
27	#[derive(Parser, Debug)]
28	#[command(name = "xtask", bin_name = "cargo xtask", max_term_width = 80)]
29	struct Cli {
30	    #[command(subcommand)]
31	    task: Task,
32	}
33	
34	/// A task.
35	#[derive(Subcommand, Debug)]
36	enum Task {
37	    /// Print the version in Cargo.toml
38	    Version,
39	
40	    /// Set the version in Cargo.toml and refresh Cargo.lock
41	    #[command(long_about = "\
42	        Set the package version in Cargo.toml, its comments and layout kept,\n\
43	        and refresh Cargo.lock in the same step, the build being --locked.\n\n\
44	        `next` adds one to the suffix's last number, 0.85.22-8 to 0.85.22-9,\n\
45	        and gives a bare version its first, -0. `bare` drops the suffix, a\n\
46	        close-out's version. Anything else is the version as written, X.Y.Z\n\
47	        or X.Y.Z-<suffix>, with one `-` at most and no `+`.")]
48	    Bump {
49	        /// `next`, `bare`, or the version as written
50	        #[arg(value_name = "next|bare|VERSION", add = ArgValueCandidates::new(bump_candidates))]
51	        to: String,
52	    },
53	
54	    /// Print a bash function that completes `cargo xtask` and its aliases
55	    #[command(long_about = "\
56	        Print a bash function that completes `cargo xtask`, and each NAME, a\n\
57	        shell alias for it such as `cx`. It holds no task names: on each tab\n\
58	        it asks the xtask of the repo the shell is in, so one copy in a\n\
59	        shell's startup file serves every repo whose xtask answers this way.\n\n\
60	        `cargo xtask <tab>` reaches it through cargo's own bash completion,\n\
61	        which hands a subcommand it does not know to the completion\n\
62	        registered for `cargo-<name>`, and needs bash-completion 2.12 or\n\
63	        later. A NAME is completed directly.\n\n\
64	        Save it once and source that file, the function being the same in\n\
65	        every repo:\n\
66	        \x20 cargo xtask completions cx > ~/.config/cargo-xtask-completion.bash")]
67	    Completions {
68	        /// A shell alias for `cargo xtask`, completed as it is
69	        #[arg(value_name = "NAME")]
70	        names: Vec<String>,
71	    },
72	}
73	
74	/// What `bump`'s argument completes to, beside a version as written.
75	fn bump_candidates() -> Vec<CompletionCandidate> {
76	    vec![
77	        CompletionCandidate::new("next")
78	            .help(Some("one more than the suffix's last number".into())),
79	        CompletionCandidate::new("bare").help(Some("the version without its suffix".into())),
80	    ]
81	}
82	
83	/// The bash function `completions` prints, registered for
84	/// `cargo-xtask`, the name cargo's completion hands `cargo xtask` to,
85	/// and for each of `names`.
86	///
87	/// It is clap's own registration script with one change: where that
88	/// calls one binary by name, this runs `cargo xtask`, so the answer is
89	/// the xtask's of the repo the shell is in. A repo with no xtask, or
90	/// one that fails, completes nothing.
91	fn completion_script(names: &[String]) -> String {
92	    let mut registered = vec!["cargo-xtask".to_string()];
93	    registered.extend(names.iter().cloned());
94	    format!(
95	        r#"# Completion for `cargo xtask`, printed by `cargo xtask completions`.
96	# It asks the xtask of the repo the shell is in, on each tab.
97	_cargo_xtask_complete() {{
98	    local IFS=$''
99	    local _CLAP_COMPLETE_INDEX=${{COMP_CWORD}}
100	    local _CLAP_COMPLETE_COMP_TYPE=${{COMP_TYPE}}
101	    if compopt +o nospace 2> /dev/null; then
102	        local _CLAP_COMPLETE_SPACE=false
103	    else
104	        local _CLAP_COMPLETE_SPACE=true
105	    fi
106	    local words=("${{COMP_WORDS[@]}}")
107	    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
108	        words[COMP_CWORD]="$2"
109	    fi
110	    COMPREPLY=( $(         _CLAP_IFS="$IFS"         _CLAP_COMPLETE_INDEX="$_CLAP_COMPLETE_INDEX"         _CLAP_COMPLETE_COMP_TYPE="$_CLAP_COMPLETE_COMP_TYPE"         _CLAP_COMPLETE_SPACE="$_CLAP_COMPLETE_SPACE"         COMPLETE="bash"         cargo xtask -- "${{words[@]}}" 2> /dev/null     ) )
111	    if [[ $? != 0 ]]; then
112	        unset COMPREPLY
113	    elif [[ $_CLAP_COMPLETE_SPACE == false ]] && [[ "${{COMPREPLY-}}" =~ [=/:]$ ]]; then
114	        compopt -o nospace
115	    fi
116	}}
117	if [[ "${{BASH_VERSINFO[0]}}" -eq 4 && "${{BASH_VERSINFO[1]}}" -ge 4 || "${{BASH_VERSINFO[0]}}" -gt 4 ]]; then
118	    complete -o nospace -o bashdefault -o nosort -F _cargo_xtask_complete {names}
119	else
120	    complete -o nospace -o bashdefault -F _cargo_xtask_complete {names}
121	fi
122	"#,
123	        names = registered.join(" ")
124	    )
125	}
126	
127	/// What `bump` is asked for.
128	#[derive(Debug, PartialEq, Eq)]
129	enum Bump {
130	    /// One more than the suffix's last number, or `-0` on a bare version.
131	    Next,
132	    /// The version without its suffix.
133	    Bare,
134	    /// The version as written.
135	    To(String),
136	}
137	
138	/// The version `bump` gives `current`.
139	///
140	/// The version is `X.Y.Z` or `X.Y.Z-<suffix>`, the suffix dot-separated
141	/// identifiers with exactly one `-` in the whole version, as the
142	/// project's suffix scheme has it. Refused: `next` on a suffix whose
143	/// last identifier is not a number, and a version written with a `+`
144	/// or a second `-`.
145	fn bumped(current: &str, bump: &Bump) -> Result<String, String> {
146	    let (public, suffix) = match current.split_once('-') {
147	        Some((public, suffix)) => (public, Some(suffix)),
148	        None => (current, None),
149	    };
150	    match bump {
151	        Bump::Bare => Ok(public.to_string()),
152	        Bump::To(version) => {
153	            let well_formed = version.matches('-').count() <= 1
154	                && !version.contains('+')
155	                && !version.is_empty()
156	                && version
157	                    .chars()
158	                    .all(|c| c.is_ascii_alphanumeric() || ".-".contains(c));
159	            match well_formed {
160	                true => Ok(version.clone()),
161	                false => Err(format!(
162	                    "'{version}' is not a version, `X.Y.Z` or `X.Y.Z-<suffix>` with one `-` and \
163	                     no `+`"
164	                )),
165	            }
166	        }
167	        Bump::Next => match suffix {
168	            None => Ok(format!("{public}-0")),
169	            Some(suffix) => {
170	                let (head, last) = match suffix.rsplit_once('.') {
171	                    Some((head, last)) => (Some(head), last),
172	                    None => (None, suffix),
173	                };
174	                let n: u64 = last.parse().map_err(|_| {
175	                    format!(
176	                        "the suffix of '{current}' ends '{last}', not a number, so `next` has \
177	                         nothing to add one to: name the version"
178	                    )
179	                })?;
180	                Ok(match head {
181	                    Some(head) => format!("{public}-{head}.{}", n + 1),
182	                    None => format!("{public}-{}", n + 1),
183	                })
184	            }
185	        },
186	    }
187	}
188	
189	/// The package version in a manifest's text.
190	fn version_in(manifest: &str) -> Result<String, String> {
191	    let doc: DocumentMut = manifest
192	        .parse()
193	        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
194	    doc.get("package")
195	        .and_then(|p| p.get("version"))
196	        .and_then(|v| v.as_str())
197	        .map(str::to_string)
198	        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())
199	}
200	
201	/// A manifest's text with the package version set to `version`, the
202	/// rest as it was, comments and layout included.
203	fn with_version(manifest: &str, version: &str) -> Result<String, String> {
204	    let mut doc: DocumentMut = manifest
205	        .parse()
206	        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
207	    let package = doc
208	        .get_mut("package")
209	        .ok_or_else(|| "Cargo.toml has no `[package]`".to_string())?;
210	    let slot = package
211	        .get_mut("version")
212	        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())?;
213	    // The decor, a trailing comment on the line among it, stays.
214	    let decor = slot.as_value().map(|v| v.decor().clone());
215	    *slot = value(version);
216	    if let (Some(decor), Some(v)) = (decor, slot.as_value_mut()) {
217	        *v.decor_mut() = decor;
218	    }
219	    Ok(doc.to_string())
220	}
221	
222	/// The workspace root, the directory above this package's.
223	fn root() -> PathBuf {
224	    Path::new(env!("CARGO_MANIFEST_DIR"))
225	        .parent()
226	        .map_or_else(|| PathBuf::from("."), Path::to_path_buf)
227	}
228	
229	/// Refresh `Cargo.lock` for the workspace's own packages, offline, so
230	/// a `--locked` build finds the version the manifest now has.
231	fn refresh_lock(root: &Path) -> Result<(), String> {
232	    // `CARGO` is the cargo that runs this task, absent only when the
233	    // binary is run by hand.
234	    let cargo = match std::env::var_os("CARGO") {
235	        Some(cargo) => cargo,
236	        None => "cargo".into(),
237	    };
238	    let status = std::process::Command::new(cargo)
239	        .args(["update", "--workspace", "--offline", "--quiet"])
240	        .current_dir(root)
241	        .status()
242	        .map_err(|e| format!("cargo update did not run: {e}"))?;
243	    match status.success() {
244	        true => Ok(()),
245	        false => Err(format!(
246	            "cargo update --workspace --offline failed: {status}"
247	        )),
248	    }
249	}
250	
251	/// Run a task, returning what it prints.
252	fn run(task: &Task) -> Result<String, String> {
253	    let manifest = root().join("Cargo.toml");
254	    let read = || std::fs::read_to_string(&manifest).map_err(|e| format!("Cargo.toml: {e}"));
255	    match task {
256	        Task::Version => version_in(&read()?),
257	        Task::Bump { to } => {
258	            let bump = match to.as_str() {
259	                "next" => Bump::Next,
260	                "bare" => Bump::Bare,
261	                version => Bump::To(version.to_string()),
262	            };
263	            let text = read()?;
264	            let current = version_in(&text)?;
265	            let new = bumped(&current, &bump)?;
266	            if new == current {
267	                return Ok(format!("{current}, as it was"));
268	            }
269	            std::fs::write(&manifest, with_version(&text, &new)?)
270	                .map_err(|e| format!("Cargo.toml: {e}"))?;
271	            refresh_lock(&root())?;
272	            Ok(format!("{current} -> {new}, Cargo.lock refreshed"))
273	        }
274	        Task::Completions { names } => Ok(completion_script(names).trim_end().to_string()),
275	    }
276	}
277	
278	fn main() -> ExitCode {
279	    // With `COMPLETE` set this answers a completion request and exits.
280	    CompleteEnv::with_factory(Cli::command).complete();
281	    match run(&Cli::parse().task) {
282	        Ok(said) => {
283	            println!("{said}");
284	            ExitCode::SUCCESS
285	        }
286	        Err(e) => {
287	            eprintln!("xtask: {e}");
288	            ExitCode::FAILURE
289	        }
290	    }
291	}
