1	//! `cargo xtask`: the project's own tasks, modelled on vc-x1's.
2	//!
3	//! - `cargo xtask version` prints the version in `Cargo.toml`.
4	//! - `cargo xtask bump <next|bare|VERSION>` sets it: `next` adds one to
5	//!   the suffix's last number, `0.85.22-8` to `0.85.22-9`, and gives a
6	//!   bare version its first, `-0`, `bare` drops the suffix, a
7	//!   close-out's version, and anything else is the version as written.
8	//!   `Cargo.lock` is refreshed in the same step, since the build is
9	//!   `--locked`.
10	//! - `cargo xtask validate [--fast]` validates the workspace, read-only:
11	//!   `cargo fmt --check`, clippy with warnings denied, and the tests,
12	//!   or with `--fast` the tests alone. Formatting is `cargo fmt`'s, run
13	//!   while working, never validation's.
14	//! - `cargo xtask run [--bin NAME] [-- ARGS]` runs the workspace's one
15	//!   binary, xtask's own left out, found by `cargo metadata`, so
16	//!   `cargo run`'s question of which binary is answered when there is
17	//!   only one to answer it with.
18	//! - `cargo xtask completions [NAME...]` prints a bash function that
19	//!   completes `cargo xtask` and each NAME, a shell alias for it, by
20	//!   asking the xtask of the repo the shell is in.
21	//!
22	//! The manifest is edited by `toml_edit`, which keeps its comments,
23	//! layout, and key order and changes the one value. The arguments are
24	//! clap's, whose completion engine answers when `COMPLETE` is set.
25	
26	use std::path::{Path, PathBuf};
27	use std::process::ExitCode;
28	
29	use clap::{CommandFactory, Parser, Subcommand};
30	use clap_complete::CompleteEnv;
31	use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};
32	use toml_edit::{DocumentMut, value};
33	
34	/// The project's own tasks.
35	#[derive(Parser, Debug)]
36	#[command(name = "xtask", bin_name = "cargo xtask", max_term_width = 80)]
37	struct Cli {
38	    #[command(subcommand)]
39	    task: Task,
40	}
41	
42	/// A task.
43	#[derive(Subcommand, Debug)]
44	enum Task {
45	    /// Print the version in Cargo.toml
46	    Version,
47	
48	    /// Set the version in Cargo.toml and refresh Cargo.lock
49	    #[command(long_about = "\
50	        Set the package version in Cargo.toml, its comments and layout kept,\n\
51	        and refresh Cargo.lock in the same step, the build being --locked.\n\n\
52	        `next` adds one to the suffix's last number, 0.85.22-8 to 0.85.22-9,\n\
53	        and gives a bare version its first, -0. `bare` drops the suffix, a\n\
54	        close-out's version. Anything else is the version as written, X.Y.Z\n\
55	        or X.Y.Z-<suffix>, with one `-` at most and no `+`.")]
56	    Bump {
57	        /// `next`, `bare`, or the version as written
58	        #[arg(value_name = "next|bare|VERSION", add = ArgValueCandidates::new(bump_candidates))]
59	        to: String,
60	    },
61	
62	    /// Validate the workspace, read-only: format check, clippy, tests
63	    #[command(long_about = "\
64	        Validate the workspace, read-only, each command in order and the\n\
65	        first failure stopping the run: `cargo fmt --check`, clippy over\n\
66	        every target with warnings denied, and every test. Nothing is\n\
67	        written, so a validation can run at any point without changing what\n\
68	        was reviewed, and formatting is `cargo fmt`'s, run while working.\n\n\
69	        --fast runs the tests of the libraries and binaries alone, for while\n\
70	        a review iterates.")]
71	    Validate {
72	        /// The tests alone, without the format check and clippy
73	        #[arg(long)]
74	        fast: bool,
75	    },
76	
77	    /// Run the workspace's one binary, passing ARGS through
78	    #[command(long_about = "\
79	        Run the workspace's binary by `cargo run --bin`, ARGS passed through\n\
80	        after `--`. The binaries are the workspace members' bin targets, as\n\
81	        `cargo metadata` reports them, xtask's own left out, and with exactly\n\
82	        one there is nothing to ask. With none or several the run is\n\
83	        refused, the binaries listed, and --bin names the one to run.")]
84	    Run {
85	        /// The binary to run, when the workspace has more than one
86	        #[arg(long, value_name = "NAME")]
