94	    #[command(long_about = "\
95	        Print a bash function that completes `cargo xtask`, and each NAME, a\n\
96	        shell alias for it such as `cx`. It holds no task names: on each tab\n\
97	        it asks the xtask of the repo the shell is in, so one copy in a\n\
98	        shell's startup file serves every repo whose xtask answers this way.\n\n\
99	        `cargo xtask <tab>` reaches it through cargo's own bash completion,\n\
100	        which hands a subcommand it does not know to the completion\n\
101	        registered for `cargo-<name>`, and needs bash-completion 2.12 or\n\
102	        later. A NAME is completed directly.\n\n\
103	        Save it once and source that file, the function being the same in\n\
104	        every repo:\n\
105	        \x20 cargo xtask completions cx > ~/.config/cargo-xtask-completion.bash")]
106	    Completions {
