113	/// What `bump`'s argument completes to, beside a version as written.
114	fn bump_candidates() -> Vec<CompletionCandidate> {
115	    vec![
116	        CompletionCandidate::new("next")
117	            .help(Some("one more than the suffix's last number".into())),
118	        CompletionCandidate::new("bare").help(Some("the version without its suffix".into())),
119	    ]
