122	/// The bash function `completions` prints, registered for
123	/// `cargo-xtask`, the name cargo's completion hands `cargo xtask` to,
124	/// and for each of `names`.
125	///
126	/// It is clap's own registration script with one change: where that
127	/// calls one binary by name, this runs `cargo xtask`, so the answer is
128	/// the xtask's of the repo the shell is in. A repo with no xtask, or
129	/// one that fails, completes nothing.
130	fn completion_script(names: &[String]) -> String {
131	    let mut registered = vec!["cargo-xtask".to_string()];
132	    registered.extend(names.iter().cloned());
133	    format!(
134	        r#"# Completion for `cargo xtask`, printed by `cargo xtask completions`.
135	# It asks the xtask of the repo the shell is in, on each tab.
136	_cargo_xtask_complete() {{
137	    local IFS=$'\013'
138	    local _CLAP_COMPLETE_INDEX=${{COMP_CWORD}}
139	    local _CLAP_COMPLETE_COMP_TYPE=${{COMP_TYPE}}
140	    if compopt +o nospace 2> /dev/null; then
141	        local _CLAP_COMPLETE_SPACE=false
142	    else
143	        local _CLAP_COMPLETE_SPACE=true
144	    fi
145	    local words=("${{COMP_WORDS[@]}}")
146	    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
147	        words[COMP_CWORD]="$2"
148	    fi
149	    COMPREPLY=( $( \
150	        _CLAP_IFS="$IFS" \
151	        _CLAP_COMPLETE_INDEX="$_CLAP_COMPLETE_INDEX" \
152	        _CLAP_COMPLETE_COMP_TYPE="$_CLAP_COMPLETE_COMP_TYPE" \
153	        _CLAP_COMPLETE_SPACE="$_CLAP_COMPLETE_SPACE" \
154	        COMPLETE="bash" \
155	        cargo xtask -- "${{words[@]}}" 2> /dev/null \
156	    ) )
157	    if [[ $? != 0 ]]; then
158	        unset COMPREPLY
159	    elif [[ $_CLAP_COMPLETE_SPACE == false ]] && [[ "${{COMPREPLY-}}" =~ [=/:]$ ]]; then
160	        compopt -o nospace
161	    fi
162	}}
163	if [[ "${{BASH_VERSINFO[0]}}" -eq 4 && "${{BASH_VERSINFO[1]}}" -ge 4 || "${{BASH_VERSINFO[0]}}" -gt 4 ]]; then
164	    complete -o nospace -o bashdefault -o nosort -F _cargo_xtask_complete {names}
165	else
166	    complete -o nospace -o bashdefault -F _cargo_xtask_complete {names}
167	fi
168	"#,
169	        names = registered.join(" ")
170	    )
171	}
