173	/// What `bump` is asked for.
174	#[derive(Debug, PartialEq, Eq)]
175	enum Bump {
176	    /// One more than the suffix's last number, or `-0` on a bare version.
177	    Next,
178	    /// The version without its suffix.
179	    Bare,
180	    /// The version as written.
181	    To(String),
182	}
183	
184	/// The version `bump` gives `current`.
185	///
186	/// The version is `X.Y.Z` or `X.Y.Z-<suffix>`, the suffix dot-separated
187	/// identifiers with exactly one `-` in the whole version, as the
188	/// project's suffix scheme has it. Refused: `next` on a suffix whose
189	/// last identifier is not a number, and a version written with a `+`
190	/// or a second `-`.
191	fn bumped(current: &str, bump: &Bump) -> Result<String, String> {
192	    let (public, suffix) = match current.split_once('-') {
193	        Some((public, suffix)) => (public, Some(suffix)),
194	        None => (current, None),
195	    };
196	    match bump {
197	        Bump::Bare => Ok(public.to_string()),
198	        Bump::To(version) => {
199	            let well_formed = version.matches('-').count() <= 1
200	                && !version.contains('+')
201	                && !version.is_empty()
202	                && version
203	                    .chars()
204	                    .all(|c| c.is_ascii_alphanumeric() || ".-".contains(c));
205	            match well_formed {
206	                true => Ok(version.clone()),
207	                false => Err(format!(
208	                    "'{version}' is not a version, `X.Y.Z` or `X.Y.Z-<suffix>` with one `-` and \
209	                     no `+`"
210	                )),
211	            }
212	        }
213	        Bump::Next => match suffix {
214	            None => Ok(format!("{public}-0")),
215	            Some(suffix) => {
216	                let (head, last) = match suffix.rsplit_once('.') {
217	                    Some((head, last)) => (Some(head), last),
218	                    None => (None, suffix),
219	                };
220	                let n: u64 = last.parse().map_err(|_| {
221	                    format!(
222	                        "the suffix of '{current}' ends '{last}', not a number, so `next` has \
223	                         nothing to add one to: name the version"
224	                    )
225	                })?;
226	                Ok(match head {
227	                    Some(head) => format!("{public}-{head}.{}", n + 1),
228	                    None => format!("{public}-{}", n + 1),
229	                })
230	            }
231	        },
232	    }
233	}
