235	/// The package version in a manifest's text.
236	fn version_in(manifest: &str) -> Result<String, String> {
237	    let doc: DocumentMut = manifest
238	        .parse()
239	        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
240	    doc.get("package")
241	        .and_then(|p| p.get("version"))
242	        .and_then(|v| v.as_str())
243	        .map(str::to_string)
244	        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())
245	}
246	
247	/// A manifest's text with the package version set to `version`, the
248	/// rest as it was, comments and layout included.
249	fn with_version(manifest: &str, version: &str) -> Result<String, String> {
250	    let mut doc: DocumentMut = manifest
251	        .parse()
252	        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
253	    let package = doc
254	        .get_mut("package")
255	        .ok_or_else(|| "Cargo.toml has no `[package]`".to_string())?;
256	    let slot = package
257	        .get_mut("version")
258	        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())?;
259	    // The decor, a trailing comment on the line among it, stays.
260	    let decor = slot.as_value().map(|v| v.decor().clone());
261	    *slot = value(version);
262	    if let (Some(decor), Some(v)) = (decor, slot.as_value_mut()) {
263	        *v.decor_mut() = decor;
264	    }
265	    Ok(doc.to_string())
266	}
