284	/// The cargo commands `validate` runs, in order, each one's arguments.
285	///
286	/// None of them writes a source file: the format is checked, never
287	/// applied.
288	fn validate_commands(fast: bool) -> Vec<Vec<&'static str>> {
289	    let tests = vec!["test", "--workspace", "--lib", "--bins"];
290	    match fast {
291	        true => vec![tests],
292	        false => vec![
293	            vec!["fmt", "--all", "--check"],
294	            vec![
295	                "clippy",
296	                "--workspace",
297	                "--all-targets",
298	                "--",
299	                "-D",
300	                "warnings",
301	            ],
302	            vec!["test", "--workspace"],
303	        ],
304	    }
305	}
306	
307	/// Run `validate`'s commands in the workspace root, each announced
308	/// before it runs, its output its own, and the first failure stopping
309	/// the run.
310	fn validate(root: &Path, fast: bool) -> Result<String, String> {
311	    let commands = validate_commands(fast);
312	    let n = commands.len();
313	    for (i, args) in commands.iter().enumerate() {
314	        let shown = format!("[{}/{n}] cargo {}", i + 1, args.join(" "));
315	        println!("validate: {shown}");
316	        let status = std::process::Command::new(cargo())
317	            .args(args)
318	            .current_dir(root)
319	            .status()
320	            .map_err(|e| format!("validate: {shown} did not run: {e}"))?;
321	        if !status.success() {
322	            return Err(format!("validate: {shown} failed: {status}"));
323	        }
324	    }
325	    let which = if fast { "fast" } else { "full" };
326	    Ok(format!("validate: {n} command(s) passed ({which})"))
327	}
