329	/// The bin targets of the workspace's packages in `cargo metadata
330	/// --no-deps` JSON, which lists the members alone, every package named
331	/// `skip` left out.
332	fn binaries(metadata: &serde_json::Value, skip: &str) -> Vec<String> {
333	    let empty = Vec::new();
334	    let packages = metadata["packages"].as_array().unwrap_or(&empty); // OK: no packages, no binaries
335	    packages
336	        .iter()
337	        .filter(|p| p["name"] != skip)
338	        .flat_map(|p| p["targets"].as_array().unwrap_or(&empty)) // OK: no targets, no binaries
339	        .filter(|t| {
340	            t["kind"]
341	                .as_array()
342	                .is_some_and(|k| k.iter().any(|k| k == "bin"))
343	        })
344	        .filter_map(|t| t["name"].as_str().map(str::to_string))
345	        .collect()
346	}
