348	/// The one binary there is to run, or why there is not one.
349	fn the_one(binaries: &[String]) -> Result<&str, String> {
350	    match binaries {
351	        [one] => Ok(one),
352	        [] => Err("run: the workspace has no binary to run".to_string()),
353	        several => Err(format!(
354	            "run: the workspace has {} binaries, name one with --bin: {}",
355	            several.len(),
356	            several.join(", ")
357	        )),
358	    }
359	}
360	
361	/// Run `bin`, or the workspace's one binary, by `cargo run`, `args`
362	/// passed through.
363	fn run_bin(root: &Path, bin: Option<&str>, args: &[String]) -> Result<String, String> {
364	    let found;
365	    let bin = match bin {
366	        Some(bin) => bin,
367	        None => {
368	            let out = std::process::Command::new(cargo())
369	                .args(["metadata", "--no-deps", "--format-version", "1"])
370	                .current_dir(root)
371	                .output()
372	                .map_err(|e| format!("run: cargo metadata did not run: {e}"))?;
373	            if !out.status.success() {
374	                return Err(format!(
375	                    "run: cargo metadata failed: {}\n{}",
376	                    out.status,
377	                    String::from_utf8_lossy(&out.stderr)
378	                ));
379	            }
380	            let metadata: serde_json::Value = serde_json::from_slice(&out.stdout)
381	                .map_err(|e| format!("run: cargo metadata's JSON does not parse: {e}"))?;
382	            found = binaries(&metadata, env!("CARGO_PKG_NAME"));
383	            the_one(&found)?
384	        }
385	    };
386	    let status = std::process::Command::new(cargo())
387	        .args(["run", "--bin", bin, "--"])
388	        .args(args)
389	        .current_dir(root)
390	        .status()
391	        .map_err(|e| format!("run: cargo run did not run: {e}"))?;
392	    match status.success() {
393	        true => Ok(String::new()),
394	        false => Err(format!("run: {bin} failed: {status}")),
395	    }
396	}
