398	/// Refresh `Cargo.lock` for the workspace's own packages, offline, so
399	/// a `--locked` build finds the version the manifest now has.
400	fn refresh_lock(root: &Path) -> Result<(), String> {
401	    let status = std::process::Command::new(cargo())
402	        .args(["update", "--workspace", "--offline", "--quiet"])
403	        .current_dir(root)
404	        .status()
405	        .map_err(|e| format!("cargo update did not run: {e}"))?;
406	    match status.success() {
407	        true => Ok(()),
408	        false => Err(format!(
409	            "cargo update --workspace --offline failed: {status}"
410	        )),
411	    }
412	}
413	
414	/// Run a task, returning what it prints.
415	fn run(task: &Task) -> Result<String, String> {
416	    let manifest = root().join("Cargo.toml");
417	    let read = || std::fs::read_to_string(&manifest).map_err(|e| format!("Cargo.toml: {e}"));
418	    match task {
419	        Task::Version => version_in(&read()?),
420	        Task::Bump { to } => {
421	            let bump = match to.as_str() {
422	                "next" => Bump::Next,
423	                "bare" => Bump::Bare,
424	                version => Bump::To(version.to_string()),
425	            };
426	            let text = read()?;
427	            let current = version_in(&text)?;
428	            let new = bumped(&current, &bump)?;
429	            if new == current {
430	                return Ok(format!("{current}, as it was"));
431	            }
432	            std::fs::write(&manifest, with_version(&text, &new)?)
433	                .map_err(|e| format!("Cargo.toml: {e}"))?;
434	            refresh_lock(&root())?;
435	            Ok(format!("{current} -> {new}, Cargo.lock refreshed"))
436	        }
437	        Task::Validate { fast } => validate(&root(), *fast),
438	        Task::Run { bin, args } => run_bin(&root(), bin.as_deref(), args),
439	        Task::Completions { names } => Ok(completion_script(names).trim_end().to_string()),
440	    }
441	}
442	
443	fn main() -> ExitCode {
444	    // With `COMPLETE` set this answers a completion request and exits.
445	    CompleteEnv::with_factory(Cli::command).complete();
446	    match run(&Cli::parse().task) {
447	        Ok(said) => {
448	            // `run` says nothing of its own, the binary's output being all.
449	            if !said.is_empty() {
450	                println!("{said}");
451	            }
452	            ExitCode::SUCCESS
453	        }
454	        Err(e) => {
455	            eprintln!("xtask: {e}");
456	            ExitCode::FAILURE
457	        }
458	    }
459	}
