617	            script.contains("cargo xtask -- \"${words[@]}\" 2> /dev/null"),
618	            "{script}"
619	        );
620	        // Registered twice over, as clap's script is: unsorted where
621	        // bash can, 4.4 and later, so the tasks keep their order.
622	        assert!(
623	            script.contains("-o nosort -F _cargo_xtask_complete cargo-xtask cx\n"),
624	            "{script}"
625	        );
626	        assert!(
627	            script.ends_with("-F _cargo_xtask_complete cargo-xtask cx\nfi\n"),
628	            "{script}"
629	        );
630	        assert!(completion_script(&[]).ends_with("_cargo_xtask_complete cargo-xtask\nfi\n"));
631	    }
632	
633	    /// The script is clap's text as written: the IFS escape is the four
634	    /// characters `\013` for bash to read, never the vertical tab itself,
635	    /// and the completer's environment is one assignment per line joined
636	    /// by `\` continuations, no run of spaces where a join was lost.
637	    #[test]
638	    fn the_completion_script_is_claps_text() {
639	        let script = completion_script(&[]);
640	        assert!(script.contains("local IFS=$'\\013'\n"), "{script}");
641	        assert!(!script.contains('\x0b'), "a raw vertical tab: {script}");
642	        assert!(
643	            script.contains("COMPREPLY=( $( \\\n        _CLAP_IFS=\"$IFS\" \\\n"),
644	            "{script}"
645	        );
646	        assert!(script.contains("2> /dev/null \\\n    ) )\n"), "{script}");
647	        let joined = script.lines().find(|l| l.trim_start().contains("   "));
648	        assert_eq!(joined, None, "a lost join leaves a run of spaces mid-line");
649	    }
650	}
