    /// and `--fast` is the tests alone, the libraries' included, which
    /// `cargo test --bins` skipped.
    #[test]
    fn validation_checks_and_never_writes() {
        let full = validate_commands(false);
        assert_eq!(full[0], ["fmt", "--all", "--check"]);
        assert!(full.iter().all(|c| c[0] != "fmt" || c.contains(&"--check")));
        assert!(
            full.iter()
                .any(|c| c[0] == "clippy" && c.ends_with(&["-D", "warnings"]))
        );
        assert!(full.iter().any(|c| c[0] == "test"));
        let fast = validate_commands(true);
        assert_eq!(fast, [["test", "--workspace", "--lib", "--bins"]]);
    }

    /// The binaries are the members' bin targets, the skipped package's
    /// and every lib left out, and one of them is the one to run.
    #[test]
    fn run_finds_the_one_binary() {
        let metadata = serde_json::json!({"packages": [
            {"name": "io-uring-x1", "targets": [
                {"name": "io_uring_x1", "kind": ["lib"]},
                {"name": "io-uring-x1", "kind": ["bin"]},
            ]},
            {"name": "xtask", "targets": [{"name": "xtask", "kind": ["bin"]}]},
        ]});
        let found = binaries(&metadata, "xtask");
        assert_eq!(found, ["io-uring-x1"]);
        assert_eq!(the_one(&found), Ok("io-uring-x1"));
        let both = binaries(&metadata, "none");
        assert_eq!(both, ["io-uring-x1", "xtask"]);
        let e = the_one(&both).unwrap_err();
        assert!(
            e.contains("2 binaries") && e.contains("io-uring-x1, xtask"),
            "{e}"
        );
        assert!(the_one(&[]).unwrap_err().contains("no binary"));
        assert_eq!(
            binaries(&serde_json::json!({}), "xtask"),
            Vec::<String>::new()
        );
    }

    /// The function asks `cargo xtask`, not a binary by name, and is
    /// registered for cargo's hand-off name and each alias given.
    #[test]
    fn the_completion_function_asks_the_repos_xtask() {
        let script = completion_script(&["cx".to_string()]);
        assert!(
            script.contains("cargo xtask -- \"${words[@]}\" 2> /dev/null"),
            "{script}"
        );
        // Registered twice over, as clap's script is: unsorted where
        // bash can, 4.4 and later, so the tasks keep their order.
        assert!(
            script.contains("-o nosort -F _cargo_xtask_complete cargo-xtask cx\n"),
            "{script}"
        );
        assert!(
            script.ends_with("-F _cargo_xtask_complete cargo-xtask cx\nfi\n"),
            "{script}"
        );
        assert!(completion_script(&[]).ends_with("_cargo_xtask_complete cargo-xtask\nfi\n"));
    }

    /// The script is clap's text as written: the IFS escape is the four
    /// characters `\013` for bash to read, never the vertical tab itself,
    /// and the completer's environment is one assignment per line joined
    /// by `\` continuations, no run of spaces where a join was lost.
    #[test]
    fn the_completion_script_is_claps_text() {
        let script = completion_script(&[]);
        assert!(script.contains("local IFS=$'\\013'\n"), "{script}");
        assert!(!script.contains('\x0b'), "a raw vertical tab: {script}");
        assert!(
            script.contains("COMPREPLY=( $( \\\n        _CLAP_IFS=\"$IFS\" \\\n"),
            "{script}"
        );
        assert!(script.contains("2> /dev/null \\\n    ) )\n"), "{script}");
        let joined = script.lines().find(|l| l.trim_start().contains("   "));
        assert_eq!(joined, None, "a lost join leaves a run of spaces mid-line");
    }
}

