//!   scheme, `Cargo.lock` refreshed in the same step.
//! - [`validate`]: the workspace validated, read-only, by the commands the
//!   caller gives, [`validate::commands`] being the default.
//! - [`run`]: the workspace's one binary run by `cargo run`, the caller's
//!   own package left out.
//! - [`completions`]: a bash function completing `cargo xtask` by asking
//!   the xtask of the repo the shell is in.
//!
//! Nothing here is compiled for one workspace: the root is found at
//! runtime by [`workspace_root`], and what is a project's own, the
//! validation commands and the package `run` leaves out, is passed in.

use std::ffi::OsString;
use std::path::PathBuf;
use std::process::Command;

pub mod completions;
pub mod run;
pub mod validate;
pub mod version;

/// The cargo that runs this task, `CARGO`, absent only when the binary
/// is run by hand.
pub fn cargo() -> OsString {
    match std::env::var_os("CARGO") {
        Some(cargo) => cargo,
        None => "cargo".into(),
    }
}

/// The root of the workspace the task is run in, as cargo finds it from
/// the current directory, the directory of the workspace's `Cargo.toml`.
pub fn workspace_root() -> Result<PathBuf, String> {
    let out = Command::new(cargo())
        .args(["locate-project", "--workspace", "--message-format", "plain"])
        .output()
        .map_err(|e| format!("cargo locate-project did not run: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "cargo locate-project failed: {}\n{}",
            out.status,
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    let manifest = PathBuf::from(String::from_utf8_lossy(&out.stdout).trim_end());
    manifest
        .parent()
        .map(PathBuf::from)
        .ok_or_else(|| format!("{} has no directory", manifest.display()))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The root holds the workspace's manifest, the one naming xtask a
    /// member, so it is the workspace's and not this package's.
    #[test]
    fn the_root_is_the_workspaces() -> Result<(), String> {
        let root = workspace_root()?;
        let manifest = std::fs::read_to_string(root.join("Cargo.toml"))
            .map_err(|e| format!("{}: {e}", root.display()))?;
        assert!(manifest.contains("[workspace]"), "{}", root.display());
        Ok(())
    }
}

//! The version in `Cargo.toml` and its bump by the suffix scheme.
//!
//! The manifest is edited by `toml_edit`, which keeps its comments,
//! layout, and key order and changes the one value, and `Cargo.lock` is
//! refreshed in the same step, since the build is `--locked`.

use std::path::Path;
use std::process::Command;

use toml_edit::{DocumentMut, value};

/// What `bump` is asked for.
#[derive(Debug, PartialEq, Eq)]
pub enum Bump {
    /// One more than the suffix's last number, or `-0` on a bare version.
    Next,
    /// The version without its suffix.
    Bare,
    /// The version as written.
    To(String),
}

impl Bump {
    /// `next`, `bare`, or a version as written.
    pub fn from_word(word: &str) -> Self {
        match word {
            "next" => Bump::Next,
            "bare" => Bump::Bare,
            version => Bump::To(version.to_string()),
        }
    }
}

/// The version in the workspace root's `Cargo.toml`.
pub fn version(root: &Path) -> Result<String, String> {
    version_in(&read(root)?)
}

/// Bump the version in the workspace root's `Cargo.toml` and refresh
/// `Cargo.lock`, saying what changed.
pub fn bump(root: &Path, bump: &Bump) -> Result<String, String> {
    let text = read(root)?;
    let current = version_in(&text)?;
    let new = bumped(&current, bump)?;
    if new == current {
        return Ok(format!("{current}, as it was"));
    }
    std::fs::write(root.join("Cargo.toml"), with_version(&text, &new)?)
        .map_err(|e| format!("Cargo.toml: {e}"))?;
    refresh_lock(root)?;
    Ok(format!("{current} -> {new}, Cargo.lock refreshed"))
}

/// The root's `Cargo.toml`, as text.
fn read(root: &Path) -> Result<String, String> {
    std::fs::read_to_string(root.join("Cargo.toml")).map_err(|e| format!("Cargo.toml: {e}"))
}

/// The version `bump` gives `current`.
///
/// The version is `X.Y.Z` or `X.Y.Z-<suffix>`, the suffix dot-separated
/// identifiers with exactly one `-` in the whole version, as the
/// project's suffix scheme has it. Refused: `next` on a suffix whose
/// last identifier is not a number, and a version written with a `+`
/// or a second `-`.
pub fn bumped(current: &str, bump: &Bump) -> Result<String, String> {
    let (public, suffix) = match current.split_once('-') {
        Some((public, suffix)) => (public, Some(suffix)),
        None => (current, None),
    };
    match bump {
        Bump::Bare => Ok(public.to_string()),
        Bump::To(version) => {
            let well_formed = version.matches('-').count() <= 1
                && !version.contains('+')
                && !version.is_empty()
                && version
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || ".-".contains(c));
            match well_formed {
                true => Ok(version.clone()),
                false => Err(format!(
                    "'{version}' is not a version, `X.Y.Z` or `X.Y.Z-<suffix>` with one `-` and \
                     no `+`"
                )),
            }
        }
        Bump::Next => match suffix {
            None => Ok(format!("{public}-0")),
            Some(suffix) => {
                let (head, last) = match suffix.rsplit_once('.') {
                    Some((head, last)) => (Some(head), last),
                    None => (None, suffix),
                };
                let n: u64 = last.parse().map_err(|_| {
                    format!(
                        "the suffix of '{current}' ends '{last}', not a number, so `next` has \
                         nothing to add one to: name the version"
                    )
                })?;
                Ok(match head {
                    Some(head) => format!("{public}-{head}.{}", n + 1),
                    None => format!("{public}-{}", n + 1),
                })
            }
        },
    }
}

/// The package version in a manifest's text.
pub fn version_in(manifest: &str) -> Result<String, String> {
    let doc: DocumentMut = manifest
        .parse()
        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
    doc.get("package")
        .and_then(|p| p.get("version"))
        .and_then(|v| v.as_str())
        .map(str::to_string)
        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())
}

/// A manifest's text with the package version set to `version`, the
/// rest as it was, comments and layout included.
pub fn with_version(manifest: &str, version: &str) -> Result<String, String> {
    let mut doc: DocumentMut = manifest
        .parse()
        .map_err(|e| format!("Cargo.toml does not parse: {e}"))?;
    let package = doc
        .get_mut("package")
        .ok_or_else(|| "Cargo.toml has no `[package]`".to_string())?;
    let slot = package
        .get_mut("version")
        .ok_or_else(|| "Cargo.toml has no `[package] version`".to_string())?;
    // The decor, a trailing comment on the line among it, stays.
    let decor = slot.as_value().map(|v| v.decor().clone());
    *slot = value(version);
    if let (Some(decor), Some(v)) = (decor, slot.as_value_mut()) {
        *v.decor_mut() = decor;
    }
    Ok(doc.to_string())
}

/// Refresh `Cargo.lock` for the workspace's own packages, offline, so
/// a `--locked` build finds the version the manifest now has.
fn refresh_lock(root: &Path) -> Result<(), String> {
    let status = Command::new(crate::cargo())
        .args(["update", "--workspace", "--offline", "--quiet"])
        .current_dir(root)
        .status()
        .map_err(|e| format!("cargo update did not run: {e}"))?;
    match status.success() {
        true => Ok(()),
        false => Err(format!(
            "cargo update --workspace --offline failed: {status}"
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// `next` walks the suffix, `bare` drops it, and a version named
    /// is taken as written when it is one.
    #[test]
    fn the_bump_follows_the_suffix_scheme() {
        let next = |v: &str| bumped(v, &Bump::Next);
        assert_eq!(next("0.85.22").unwrap(), "0.85.22-0");
        assert_eq!(next("0.85.22-0").unwrap(), "0.85.22-1");
        assert_eq!(next("0.85.22-9").unwrap(), "0.85.22-10");
        assert_eq!(next("0.85.22-3.1").unwrap(), "0.85.22-3.2");
        assert!(next("0.85.22-rc").unwrap_err().contains("not a number"));
        assert_eq!(bumped("0.85.22-12", &Bump::Bare).unwrap(), "0.85.22");
        assert_eq!(bumped("0.85.22", &Bump::Bare).unwrap(), "0.85.22");
        let to = |v: &str| bumped("0.85.22-1", &Bump::To(v.to_string()));
        assert_eq!(to("0.86.0-0").unwrap(), "0.86.0-0");
        for bad in ["", "1.0.0-1-2", "1.0.0+build", "1.0.0 "] {
            assert!(to(bad).is_err(), "{bad}");
        }
    }

    /// The words name the bumps, and anything else is a version.
    #[test]
    fn a_word_names_its_bump() {
        assert_eq!(Bump::from_word("next"), Bump::Next);
        assert_eq!(Bump::from_word("bare"), Bump::Bare);
        assert_eq!(Bump::from_word("1.2.3"), Bump::To("1.2.3".to_string()));
    }

    /// The version's value changes and nothing else does: the comments,
    /// the blank lines, the key order, and a dependency's own version.
    #[test]
    fn the_manifest_keeps_its_comments_and_layout() {
        let manifest = "\
[package]
name = \"vc-x1\"
version = \"0.85.22-8\" # the version-of-record
edition = \"2024\"

# A comment between tables.
[dependencies]
clap = { version = \"4.6\", features = [\"derive\"] }
# The rng jj-lib takes.
rand = \"0.10\"
";
        assert_eq!(version_in(manifest).unwrap(), "0.85.22-8");
        let new = with_version(manifest, "0.85.22-9").unwrap();
        assert_eq!(new, manifest.replace("0.85.22-8", "0.85.22-9"));
        assert!(with_version("[workspace]\n", "1.0.0").is_err());
    }
}

//! The workspace validated, read-only, by a list of cargo commands.
//!
//! Nothing is written, so a validation can run at any point without
//! changing what was reviewed, and formatting is `cargo fmt`'s, run while
//! working.

use std::path::Path;
use std::process::Command;

/// The default cargo commands, in order, each one's arguments: a format
/// check, clippy over every target with warnings denied, and every test,
/// or with `fast` the libraries' and binaries' tests alone.
///
/// None of them writes a source file: the format is checked, never
/// applied.
pub fn commands(fast: bool) -> Vec<Vec<&'static str>> {
    let tests = vec!["test", "--workspace", "--lib", "--bins"];
    match fast {
        true => vec![tests],
        false => vec![
            vec!["fmt", "--all", "--check"],
            vec![
                "clippy",
                "--workspace",
                "--all-targets",
                "--",
                "-D",
                "warnings",
            ],
            vec!["test", "--workspace"],
        ],
    }
}

/// Run `commands` by cargo in the workspace root, each announced before
/// it runs, its output its own, and the first failure stopping the run.
/// `label` names the set in the closing line, `full` or `fast`.
pub fn validate(root: &Path, commands: &[Vec<&str>], label: &str) -> Result<String, String> {
    let n = commands.len();
    for (i, args) in commands.iter().enumerate() {
        let shown = format!("[{}/{n}] cargo {}", i + 1, args.join(" "));
        println!("validate: {shown}");
        let status = Command::new(crate::cargo())
            .args(args)
            .current_dir(root)
            .status()
            .map_err(|e| format!("validate: {shown} did not run: {e}"))?;
        if !status.success() {
            return Err(format!("validate: {shown} failed: {status}"));
        }
    }
    Ok(format!("validate: {n} command(s) passed ({label})"))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Validation is read-only, the format checked and never applied,
    /// and `fast` is the tests alone, the libraries' included, which
    /// `cargo test --bins` skipped.
    #[test]
    fn validation_checks_and_never_writes() {
        let full = commands(false);
        assert_eq!(full[0], ["fmt", "--all", "--check"]);
        assert!(full.iter().all(|c| c[0] != "fmt" || c.contains(&"--check")));
        assert!(
            full.iter()
                .any(|c| c[0] == "clippy" && c.ends_with(&["-D", "warnings"]))
        );
        assert!(full.iter().any(|c| c[0] == "test"));
        let fast = commands(true);
        assert_eq!(fast, [["test", "--workspace", "--lib", "--bins"]]);
    }
}

//! The workspace's one binary, run by `cargo run`.
//!
//! The binaries are the workspace members' bin targets, as `cargo
//! metadata` reports them, the caller's own package left out, so a
//! workspace with one binary beside its xtask never asks which.

use std::path::Path;
use std::process::Command;

/// Run `bin`, or the workspace's one binary, every package named `skip`
/// left out, by `cargo run`, `args` passed through. Says nothing of its
/// own, the binary's output being all.
pub fn run(root: &Path, bin: Option<&str>, args: &[String], skip: &str) -> Result<String, String> {
    let found;
    let bin = match bin {
        Some(bin) => bin,
        None => {
            found = binaries(&metadata(root)?, skip);
            the_one(&found)?
        }
    };
    let status = Command::new(crate::cargo())
        .args(["run", "--bin", bin, "--"])
        .args(args)
        .current_dir(root)
        .status()
        .map_err(|e| format!("run: cargo run did not run: {e}"))?;
    match status.success() {
        true => Ok(String::new()),
        false => Err(format!("run: {bin} failed: {status}")),
    }
}

/// The workspace's `cargo metadata --no-deps`, parsed.
fn metadata(root: &Path) -> Result<serde_json::Value, String> {
    let out = Command::new(crate::cargo())
        .args(["metadata", "--no-deps", "--format-version", "1"])
        .current_dir(root)
        .output()
        .map_err(|e| format!("run: cargo metadata did not run: {e}"))?;
    if !out.status.success() {
        return Err(format!(
            "run: cargo metadata failed: {}\n{}",
            out.status,
            String::from_utf8_lossy(&out.stderr)
        ));
    }
    serde_json::from_slice(&out.stdout)
        .map_err(|e| format!("run: cargo metadata's JSON does not parse: {e}"))
}

/// The bin targets of the workspace's packages in `cargo metadata
/// --no-deps` JSON, which lists the members alone, every package named
/// `skip` left out.
pub fn binaries(metadata: &serde_json::Value, skip: &str) -> Vec<String> {
    let empty = Vec::new();
    let packages = metadata["packages"].as_array().unwrap_or(&empty); // OK: no packages, no binaries
    packages
        .iter()
        .filter(|p| p["name"] != skip)
        .flat_map(|p| p["targets"].as_array().unwrap_or(&empty)) // OK: no targets, no binaries
        .filter(|t| {
            t["kind"]
                .as_array()
                .is_some_and(|k| k.iter().any(|k| k == "bin"))
        })
        .filter_map(|t| t["name"].as_str().map(str::to_string))
        .collect()
}

/// The one binary there is to run, or why there is not one.
pub fn the_one(binaries: &[String]) -> Result<&str, String> {
    match binaries {
        [one] => Ok(one),
        [] => Err("run: the workspace has no binary to run".to_string()),
        several => Err(format!(
            "run: the workspace has {} binaries, name one with --bin: {}",
            several.len(),
            several.join(", ")
        )),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The binaries are the members' bin targets, the skipped package's
    /// and every lib left out, and one of them is the one to run.
    #[test]
    fn run_finds_the_one_binary() {
        let metadata = serde_json::json!({"packages": [
            {"name": "io-uring-x1", "targets": [
                {"name": "io_uring_x1", "kind": ["lib"]},
                {"name": "io-uring-x1", "kind": ["bin"]},
            ]},
            {"name": "xtask", "targets": [{"name": "xtask", "kind": ["bin"]}]},
        ]});
        let found = binaries(&metadata, "xtask");
        assert_eq!(found, ["io-uring-x1"]);
        assert_eq!(the_one(&found), Ok("io-uring-x1"));
        let both = binaries(&metadata, "none");
        assert_eq!(both, ["io-uring-x1", "xtask"]);
        let e = the_one(&both).unwrap_err();
        assert!(
            e.contains("2 binaries") && e.contains("io-uring-x1, xtask"),
            "{e}"
        );
        assert!(the_one(&[]).unwrap_err().contains("no binary"));
        assert_eq!(
            binaries(&serde_json::json!({}), "xtask"),
            Vec::<String>::new()
        );
    }

    /// This workspace's metadata, read for real, has the project's
    /// binary once xtask's is left out, the lib target never counted.
    #[test]
    fn this_workspace_has_one_binary_beside_xtask() -> Result<(), String> {
        let found = binaries(&metadata(&crate::workspace_root()?)?, "xtask");
        assert_eq!(found, ["io-uring-x1"]);
        Ok(())
    }
}

//! A bash function completing `cargo xtask` and its aliases.

/// The bash function `completions` prints, registered for
/// `cargo-xtask`, the name cargo's completion hands `cargo xtask` to,
/// and for each of `names`.
///
/// It is clap's own registration script with one change: where that
/// calls one binary by name, this runs `cargo xtask`, so the answer is
/// the xtask's of the repo the shell is in. A repo with no xtask, or
/// one that fails, completes nothing.
pub fn script(names: &[String]) -> String {
    let mut registered = vec!["cargo-xtask".to_string()];
    registered.extend(names.iter().cloned());
    format!(
        r#"# Completion for `cargo xtask`, printed by `cargo xtask completions`.
# It asks the xtask of the repo the shell is in, on each tab.
_cargo_xtask_complete() {{
    local IFS=$'\013'
    local _CLAP_COMPLETE_INDEX=${{COMP_CWORD}}
    local _CLAP_COMPLETE_COMP_TYPE=${{COMP_TYPE}}
    if compopt +o nospace 2> /dev/null; then
        local _CLAP_COMPLETE_SPACE=false
    else
        local _CLAP_COMPLETE_SPACE=true
    fi
    local words=("${{COMP_WORDS[@]}}")
    if [[ "${{BASH_VERSINFO[0]}}" -ge 4 ]]; then
        words[COMP_CWORD]="$2"
    fi
    COMPREPLY=( $( \
        _CLAP_IFS="$IFS" \
        _CLAP_COMPLETE_INDEX="$_CLAP_COMPLETE_INDEX" \
        _CLAP_COMPLETE_COMP_TYPE="$_CLAP_COMPLETE_COMP_TYPE" \
        _CLAP_COMPLETE_SPACE="$_CLAP_COMPLETE_SPACE" \
        COMPLETE="bash" \
        cargo xtask -- "${{words[@]}}" 2> /dev/null \
    ) )
    if [[ $? != 0 ]]; then
        unset COMPREPLY
    elif [[ $_CLAP_COMPLETE_SPACE == false ]] && [[ "${{COMPREPLY-}}" =~ [=/:]$ ]]; then
        compopt -o nospace
    fi
}}
if [[ "${{BASH_VERSINFO[0]}}" -eq 4 && "${{BASH_VERSINFO[1]}}" -ge 4 || "${{BASH_VERSINFO[0]}}" -gt 4 ]]; then
    complete -o nospace -o bashdefault -o nosort -F _cargo_xtask_complete {names}
else
    complete -o nospace -o bashdefault -F _cargo_xtask_complete {names}
fi
"#,
        names = registered.join(" ")
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The function asks `cargo xtask`, not a binary by name, and is
    /// registered for cargo's hand-off name and each alias given.
    #[test]
    fn the_completion_function_asks_the_repos_xtask() {
        let script = script(&["cx".to_string()]);
        assert!(
            script.contains("cargo xtask -- \"${words[@]}\" 2> /dev/null"),
            "{script}"
        );
        // Registered twice over, as clap's script is: unsorted where
        // bash can, 4.4 and later, so the tasks keep their order.
        assert!(
            script.contains("-o nosort -F _cargo_xtask_complete cargo-xtask cx\n"),
            "{script}"
        );
        assert!(
            script.ends_with("-F _cargo_xtask_complete cargo-xtask cx\nfi\n"),
            "{script}"
        );
        assert!(super::script(&[]).ends_with("_cargo_xtask_complete cargo-xtask\nfi\n"));
    }

    /// The script is clap's text as written: the IFS escape is the four
    /// characters `\013` for bash to read, never the vertical tab itself,
    /// and the completer's environment is one assignment per line joined
    /// by `\` continuations, no run of spaces where a join was lost.
    #[test]
    fn the_completion_script_is_claps_text() {
        let script = script(&[]);
        assert!(script.contains("local IFS=$'\\013'\n"), "{script}");
        assert!(!script.contains('\x0b'), "a raw vertical tab: {script}");
        assert!(
            script.contains("COMPREPLY=( $( \\\n        _CLAP_IFS=\"$IFS\" \\\n"),
            "{script}"
        );
        assert!(script.contains("2> /dev/null \\\n    ) )\n"), "{script}");
        let joined = script.lines().find(|l| l.trim_start().contains("   "));
        assert_eq!(joined, None, "a lost join leaves a run of spaces mid-line");
    }
}

