            Ok(Task::Validate { fast: false })
        ));
        assert!(matches!(
            parse(&["xtask", "validate", "--fast"]),
            Ok(Task::Validate { fast: true })
        ));
        assert!(matches!(
            parse(&["xtask", "run"]),
            Ok(Task::Run { bin: None, args }) if args.is_empty()
        ));
        assert!(matches!(
