    ring: Ring,
    requests: Consumer<'a>,
    completions: Producer<'a>,
    /// Requests in the SQ or the kernel whose CQEs are not yet copied out: kept at most the CQ's
    /// depth, so the kernel never has more completions than the CQ holds.
    in_flight: u32,
}

impl<'a> Driver<'a> {
