        while seen < 8 {
            while let Ok(c) = cmp_rx.reserve_slot_with::<NopCompletion>(|_| false) {
                assert_eq!(c.res, 0);
                c.release();
                seen += 1;
            }
            driver.step(true).or_dbg()?;
        }
        assert_eq!(driver.in_flight(), 0);
