28	/// Set up a ring of `depths`, send the NOPs through it in batches the SQ holds, and print each
29	/// completion and the ring's indexes.
30	fn round_trip(depths: Depths) -> Result<(), Box<dyn Error>> {
31	    // The kernel's refusal is a bare errno, so the depths it refused are named beside it.
32	    let mut ring = Ring::with_depths(depths).map_err(|e| {
33	        format!(
34	            "io_uring_setup refused {depths:?} (the CQ must be at least the SQ, and neither 0): {e}"
35	        )
36	    })?;
37	    println!("set up:    {:?}", ring.state());
